PRAGMA foreign_keys = ON;
CREATE TABLE households (id TEXT PRIMARY KEY, name TEXT NOT NULL, currency TEXT NOT NULL DEFAULT 'EUR', created_at TEXT NOT NULL);
CREATE TABLE members (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE incomes (id TEXT PRIMARY KEY, member_id TEXT NOT NULL REFERENCES members(id), amount_cents INTEGER NOT NULL CHECK(amount_cents >= 0), effective_from TEXT NOT NULL, effective_to TEXT);
CREATE TABLE monthly_budgets (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), year INTEGER NOT NULL, month INTEGER NOT NULL CHECK(month BETWEEN 1 AND 12), status TEXT NOT NULL CHECK(status IN ('DRAFT','ACTIVE','CLOSED')), created_at TEXT NOT NULL, closed_at TEXT, UNIQUE(household_id,year,month));
CREATE TABLE monthly_budget_lines (id TEXT PRIMARY KEY, monthly_budget_id TEXT NOT NULL REFERENCES monthly_budgets(id), name TEXT NOT NULL, planned_amount_cents INTEGER NOT NULL CHECK(planned_amount_cents >= 0), allocation_type TEXT NOT NULL, expense_group TEXT NOT NULL DEFAULT 'DAILY_LIFE' CHECK(expense_group IN ('HOUSING','DAILY_LIFE')), status TEXT NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE budget_line_shares (budget_line_id TEXT NOT NULL REFERENCES monthly_budget_lines(id), member_id TEXT NOT NULL REFERENCES members(id), weight INTEGER NOT NULL, expected_amount_cents INTEGER NOT NULL, PRIMARY KEY(budget_line_id,member_id));
CREATE TABLE contribution_transactions (id TEXT PRIMARY KEY, monthly_budget_id TEXT NOT NULL REFERENCES monthly_budgets(id), member_id TEXT NOT NULL REFERENCES members(id), amount_cents INTEGER NOT NULL, transaction_date TEXT NOT NULL, note TEXT, created_at TEXT NOT NULL);
CREATE TABLE expenses (id TEXT PRIMARY KEY, monthly_budget_line_id TEXT NOT NULL REFERENCES monthly_budget_lines(id), amount_cents INTEGER NOT NULL CHECK(amount_cents > 0), transaction_date TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, reversed_by_id TEXT REFERENCES expenses(id));
CREATE TABLE surplus_transactions (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), monthly_budget_id TEXT REFERENCES monthly_budgets(id), amount_cents INTEGER NOT NULL, type TEXT NOT NULL, description TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE UNIQUE INDEX one_closing_surplus_per_month ON surplus_transactions(monthly_budget_id) WHERE type = 'MONTH_CLOSE';
CREATE TABLE projects (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), name TEXT NOT NULL, target_amount_cents INTEGER, status TEXT NOT NULL, created_at TEXT NOT NULL, archived_at TEXT);
CREATE TABLE project_allocations (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), amount_cents INTEGER NOT NULL, description TEXT NOT NULL, created_at TEXT NOT NULL);
